def find_hollow_rectangles(grid):
    h, w = len(grid), len(grid[0])
    hollows = []  # (r, c, height, width) of hollow rectangle corners
    seen = set()

    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0:
                # Check for top-left corner of hollow rectangle
                # Need non-zero neighbors on top and left edges
                if r > 0 and c > 0:
                    if grid[r-1][c] != 0 and grid[r][c-1] != 0:
                        # Try to find rectangle
                        for height in range(2, 8):
                            for width in range(2, 8):
                                if (r, c, height, width) in seen:
                                    continue
                                # Check if boundary is filled with non-zero
                                is_hollow = True

                                # Top edge (already know r-1,c is non-zero)
                                for cc in range(c+1, c+width):
                                    if grid[r-1][cc] == 0:
                                        is_hollow = False
                                        break
                                if not is_hollow:
                                    break

                                # Bottom edge
                                for cc in range(c+1, c+width):
                                    if grid[r+height-1][cc] == 0:
                                        is_hollow = False
                                        break
                                if not is_hollow:
                                    break

                                # Left edge (already know r,c-1 is non-zero)
                                for rr in range(r+1, r+height):
                                    if grid[rr][c-1] == 0:
                                        is_hollow = False
                                        break
                                if not is_hollow:
