                                # Right edge
                                for rr in range(r+1, r+height):
                                    if grid[rr][c+width-1] == 0:
                                        is_hollow = False
                                        break
                                if not is_hollow:
                                    break

                                # Check interior are 0s
                                interior_zero = True
                                for rr in range(r+1, r+height-1):
