# Actually just group by distance
def group_by_nearby(points, max_dist=3):
    grouped = {}
    for i, p1 in enumerate(points):
        group_key = i
        for p2 in points[i+1:]:
            if abs(p1[0]-p2[0]) + abs(p1[1]-p2[1]) <= max_dist:
                group_key = i
                break
        grouped.setdefault(group_key, []).append(p1)

    # Merge overlapping groups
    merged = []
    for g in grouped.values():
        new_merged = g
        for other in grouped.values():
            if new_merged != other:
                if any(abs((a[0]-b[0])) <= max_dist for a in g for b in other):
                    new_merged = g + other
        if new_merged not in merged:
            merged.append(new_merged)

    return merged

