def regions_overlap(r1, r2):
    # Two 5x4 regions overlap if they share at least one cell on their border
    # For merge, we want border-adjacency (edge-shares)
    rmin1, cmin1, rmax1, cmax1 = r1
    rmin2, cmin2, rmax2, cmax2 = r2

    # Horizontal adjacency: same row overlap, columns are adjacent
    if max(rmin1, rmin2) <= min(rmax1, rmax2):
        # Overlap in rows, and columns touch
        if abs(cmin1 - cmax2) == 1 and abs(cmin2 - cmax1) == 1:
            return True

    # Vertical adjacency: same column overlap, rows are adjacent  
    if max(cmin1, cmin2) <= min(cmax1, cmax2):
        # Overlap in columns, and rows touch
        if abs(rmin1 - rmax2) == 1 and abs(rmin2 - rmax1) == 1:
            return True

    return False

